"""Optional recorded-calendar-date checks; no causal or historical promise claims."""
import argparse,pathlib,time,collections,decimal,datetime,csv
from common import load,save,db,query,csvwrite
def run(package):
    import pyarrow.parquet as pq
    p=pathlib.Path(package);assert load(p/'manifest.json').get('p2_status')=='pass';assert (p/'evidence/candidates/history_verdict.json').exists();start=time.perf_counter();c=db(p);out=p/'evidence/candidates'
    def export(name,sql):
        (p/'sql/local'/f'{name}.sql').write_text(sql,encoding='utf-8');cols,rr=query(c,sql);csvwrite(out/f'{name}.csv',cols,rr);return rr
    supplier=export('supplier_lateness',"SELECT strftime(p.OrderDate,'%Y-%m') AS Month,COUNT(*) AS EligibleLines,COUNT(*) FILTER(WHERE l.LastReceiptDate>p.ExpectedDeliveryDate) AS LateLines FROM raw.Purchasing_PurchaseOrders p JOIN raw.Purchasing_PurchaseOrderLines l USING(PurchaseOrderID) WHERE l.IsOrderLineFinalized AND l.ReceivedOuters=l.OrderedOuters AND l.LastReceiptDate IS NOT NULL AND p.ExpectedDeliveryDate IS NOT NULL GROUP BY 1 ORDER BY 1")
    customer=export('customer_lateness',"SELECT strftime(i.InvoiceDate,'%Y-%m') AS Month,COUNT(*) AS ConfirmedInvoices,COUNT(*) FILTER(WHERE CAST(i.ConfirmedDeliveryTime AS DATE)>o.ExpectedDeliveryDate) AS LaterCalendarConfirmations FROM raw.Sales_Invoices i JOIN raw.Sales_Orders o USING(OrderID) WHERE i.ConfirmedDeliveryTime IS NOT NULL AND o.ExpectedDeliveryDate IS NOT NULL GROUP BY 1 ORDER BY 1")
    export('supplier_lateness_examples',"SELECT p.PurchaseOrderID,l.PurchaseOrderLineID,l.StockItemID,p.SupplierID,p.ExpectedDeliveryDate,l.LastReceiptDate,l.OrderedOuters,l.ReceivedOuters,l.IsOrderLineFinalized,l.LastReceiptDate>p.ExpectedDeliveryDate AS LaterCalendarDate FROM raw.Purchasing_PurchaseOrders p JOIN raw.Purchasing_PurchaseOrderLines l USING(PurchaseOrderID) WHERE l.LastReceiptDate IS NOT NULL ORDER BY LaterCalendarDate DESC,l.PurchaseOrderLineID LIMIT 20")
    export('customer_lateness_examples',"SELECT i.InvoiceID,i.OrderID,i.InvoiceDate,o.ExpectedDeliveryDate,i.ConfirmedDeliveryTime,i.ReturnedDeliveryData,CAST(i.ConfirmedDeliveryTime AS DATE)>o.ExpectedDeliveryDate AS LaterCalendarDate FROM raw.Sales_Invoices i JOIN raw.Sales_Orders o USING(OrderID) WHERE i.ConfirmedDeliveryTime IS NOT NULL ORDER BY LaterCalendarDate DESC,i.InvoiceID LIMIT 20")
    po={r['PurchaseOrderID']:r for r in pq.read_table(p/'data/raw/Purchasing.PurchaseOrders.parquet').to_pylist()};pol=pq.read_table(p/'data/raw/Purchasing.PurchaseOrderLines.parquet').to_pylist();oo={r['OrderID']:r for r in pq.read_table(p/'data/raw/Sales.Orders.parquet').to_pylist()};inv=pq.read_table(p/'data/raw/Sales.Invoices.parquet').to_pylist();sd=collections.defaultdict(lambda:[0,0]);cd=collections.defaultdict(lambda:[0,0])
    for l in pol:
        o=po[l['PurchaseOrderID']]
        if l['IsOrderLineFinalized'] and l['ReceivedOuters']==l['OrderedOuters'] and l['LastReceiptDate'] is not None and o['ExpectedDeliveryDate'] is not None:
            g=sd[o['OrderDate'].strftime('%Y-%m')];g[0]+=1;g[1]+=l['LastReceiptDate']>o['ExpectedDeliveryDate']
    for i in inv:
        o=oo.get(i['OrderID'])
        if o and i['ConfirmedDeliveryTime'] is not None and o['ExpectedDeliveryDate'] is not None:
            g=cd[i['InvoiceDate'].strftime('%Y-%m')];g[0]+=1;g[1]+=i['ConfirmedDeliveryTime'].date()>o['ExpectedDeliveryDate']
    assert supplier==[(k,*v) for k,v in sorted(sd.items())];assert customer==[(k,*v) for k,v in sorted(cd.items())]
    multiple=collections.Counter(i['OrderID'] for i in inv if i['OrderID'] is not None)
    counts={'purchase_lines':len(pol),'eligible_purchase_lines':sum(v[0] for v in sd.values()),'late_purchase_lines':sum(v[1] for v in sd.values()),'null_receipt_lines':sum(l['LastReceiptDate'] is None for l in pol),'nonfinal_or_not_fully_received_lines':sum(not l['IsOrderLineFinalized'] or l['ReceivedOuters']!=l['OrderedOuters'] for l in pol),'received_over_ordered_lines':sum(l['ReceivedOuters']>l['OrderedOuters'] for l in pol),'null_expected_po_lines':sum(po[l['PurchaseOrderID']]['ExpectedDeliveryDate'] is None for l in pol),'invoices':len(inv),'confirmed_eligible_invoices':sum(v[0] for v in cd.values()),'later_calendar_confirmations':sum(v[1] for v in cd.values()),'null_confirmed_invoices':sum(i['ConfirmedDeliveryTime'] is None for i in inv),'null_order_invoices':sum(i['OrderID'] is None for i in inv),'orphan_order_invoices':sum(i['OrderID'] is not None and i['OrderID'] not in oo for i in inv),'orders_with_multiple_invoices':sum(v>1 for v in multiple.values()),'confirmation_before_invoice_date':sum(i['ConfirmedDeliveryTime'] is not None and i['ConfirmedDeliveryTime'].date()<i['InvoiceDate'] for i in inv)}
    rates=[]
    for side,d in [('supplier',sd),('customer',cd)]:
        for month,(n,late) in sorted(d.items()):rates.append([side,month,n,late,n-late,str(decimal.Decimal(late)/n) if n else None])
    csvwrite(out/'lateness_monthly_rates.csv',['side','month','eligible_denominator','positive','zero_not_after','rate'],rates)
    save(out/'lateness_verdict.json',{'status':'candidate-not-dashboard','supplier_chart':'rejected uniform zero recorded lateness' if counts['late_purchase_lines']==0 else 'candidate stored-date comparison only','customer_chart':'rejected uniform zero recorded lateness' if counts['later_calendar_confirmations']==0 else 'candidate stored-date comparison only','counts':counts,'independent_oracle':'Python raw Parquet rows; monthly groups match SQL exactly','supplier_definition':'eligible finalized fully received purchase lines: recorded last receipt calendar date > stored expected PO calendar date','supplier_semantics':'last recorded receipt date, not first receipt; no certified original-promise history or complete movement classification','customer_definition':'confirmed invoice grain: confirmation calendar date > referenced order stored expected calendar date; no original/backorder promise collapse','missing_values':'excluded as unknown, reported separately; not on-time','date_convention':'calendar dates, naive source timestamps; no midnight deadline comparison','join_grain':'purchase line to one PO / invoice to one order; PK/FK parity and independent row comparisons prevent multiplying joins','causal_claims':'unsupported; no conclusion that supplier failure caused May backlog growth','budget_minutes':120,'elapsed_seconds':time.perf_counter()-start,'source_access':'none; local acquired evidence only'})
    c.close();print('P3 recorded lateness reviewed',counts,flush=True)
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--package',required=True);ap.add_argument('--stage',required=True,choices=['p3']);ap.add_argument('--investigation',required=True,choices=['lateness']);a=ap.parse_args();run(a.package)
